    except ValueError as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
    try:
        timezone.utc.fromutc('not datetime')
    except TypeError as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
    for tz in [self.EST, self.ACDT, Eastern]:
        utctime = self.DT.replace(tzinfo=tz)
        local = tz.fromutc(utctime)
        assert local - utctime == tz.utcoffset(local), ('assertEqual', local - utctime, tz.utcoffset(local))
        assert local == self.DT.replace(tzinfo=timezone.utc), ('assertEqual', local, self.DT.replace(tzinfo=timezone.utc))
